(function(){
  'use strict';
  const C=window.StepInvoiceCore,P=window.StepInvoicePdf;
  const DEFAULT_API_URL='https://script.google.com/macros/s/AKfycbwo1DdSQ2eUVVU35v1TqermHTgIEsT1u4U-M_67KfA50VelbHsh28W_pec56OlyBkxqaw/exec';
  const STAFF_AUTH_KEY='stepStaffAppAuth';
  const VIEWS=new Set(['create','invoices','partners','history','settings','mail']);
  const savedPartners=JSON.parse(localStorage.getItem('stepInvoicePartners')||'[]');
  const savedSettings=JSON.parse(localStorage.getItem('stepInvoiceSettings')||'{}');
  if(!savedSettings.apiUrl)savedSettings.apiUrl=DEFAULT_API_URL;
  const state={partners:[...new Map([...C.DEMO_PARTNERS,...savedPartners].map(p=>[p['顧客コード'],p])).values()],invoices:[],history:[],preview:null,selected:new Set(),selectedInvoiceNumber:'',invoiceDetailTab:'preview',invoiceFilters:{dateField:'createdAt',from:'',to:'',query:''},pendingResend:null,pendingDisable:null,pendingDeletePartnerCode:null,pendingDeleteInvoiceNumber:null,resendSubmitting:false,editingPartnerCode:null,studentCandidate:null,postalRequest:0,settings:savedSettings};
  const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const localIso=date=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
  const plusDays=(dateValue,days)=>{const [year,month,day]=String(dateValue).split('-').map(Number),date=new Date(year,month-1,day);date.setDate(date.getDate()+days);return localIso(date);};
  function alert(message,type='warning'){const el=$('#globalAlert');el.textContent=message;el.className=`alert ${type}`;setTimeout(()=>el.classList.add('hidden'),7000);}
  function activateStep(index){$$('#createSteps li').forEach((el,i)=>{el.classList.toggle('active',i===index);el.classList.toggle('done',i<index);});}
  function showView(name){const view=VIEWS.has(name)?name:'invoices';$$('.view').forEach(x=>x.classList.remove('active'));$(`#view-${view}`).classList.add('active');$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));if(location.hash!==`#${view}`)history.replaceState(null,'',`#${view}`);if(view==='invoices')renderInvoices();}
  function setCreateMethod(method){$$('[data-create-method]').forEach(button=>{const active=button.dataset.createMethod===method;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));});$('#createCsvPane').classList.toggle('active',method==='csv');$('#createSinglePane').classList.toggle('active',method==='single');if(method==='single')prepareSingleInvoice();}
  function setSingleDefaults(force=false){const form=$('#singleInvoiceForm'),date=form.elements.invoiceDate;if(!date.value)date.value=localIso(new Date());if(force||!form.elements.dueDate.value)form.elements.dueDate.value=plusDays(date.value,21);if(force||!form.elements.invoiceNumber.value)form.elements.invoiceNumber.value=C.nextInvoiceNumber(date.value,state.invoices);if(force||!form.elements.subject.value){const [year,month]=date.value.split('-');form.elements.subject.value=`${year}年${Number(month)}月分`;}}
  function updateSingleFromDate(){const form=$('#singleInvoiceForm'),date=form.elements.invoiceDate.value;if(!date)return;form.elements.dueDate.value=plusDays(date,21);form.elements.invoiceNumber.value=C.nextInvoiceNumber(date,state.invoices);const [year,month]=date.split('-');form.elements.subject.value=`${year}年${Number(month)}月分`;}
  async function prepareSingleInvoice(){setSingleDefaults();if(!state.settings.apiUrl)return;try{const data=await api('getDashboard');if(Array.isArray(data.invoices)){const merged=new Map(data.invoices.map(invoice=>[String(invoice.invoiceNumber),invoice]));state.invoices.forEach(invoice=>merged.set(String(invoice.invoiceNumber),invoice));state.invoices=[...merged.values()];renderCreate();setSingleDefaults(true);}}catch(e){alert(`保存済み請求書の確認に失敗しました：${e.message}`,'error');}}
  function persistPartners(){localStorage.setItem('stepInvoicePartners',JSON.stringify(state.partners));}
  function renderPartnerOptions(){const select=$('#singlePartner'),selected=select.value;select.innerHTML='<option value="">取引先を選択してください</option>'+state.partners.map(p=>`<option value="${esc(p['顧客コード'])}">${esc(p['顧客コード'])}　${esc(p['名称'])}（${esc(p['メールアドレス']||'メール未登録')}）</option>`).join('');if(state.partners.some(p=>p['顧客コード']===selected))select.value=selected;}
  async function api(action,payload={}){
    const url=state.settings.apiUrl;if(!url)throw new Error('基本設定でApps ScriptデプロイURLを設定してください。');
    let staffAuth=null;try{staffAuth=JSON.parse(localStorage.getItem(STAFF_AUTH_KEY)||'null');}catch(_){}
    const requestId=`step-${Date.now()}-${Math.random().toString(36).slice(2)}`;
    const bridgeNonce=[...crypto.getRandomValues(new Uint32Array(4))].map(x=>x.toString(16).padStart(8,'0')).join('');
    const frame=document.createElement('iframe');frame.name=requestId;frame.hidden=true;document.body.appendChild(frame);
    const form=document.createElement('form');form.method='POST';form.action=url;form.target=requestId;form.hidden=true;
    const fields={bridge:'1',requestId,bridgeNonce,action,payload:JSON.stringify(payload),authToken:state.settings.adminApiKey||'',systemPortalSessionToken:staffAuth?.systemPortalSessionToken||''};
    Object.entries(fields).forEach(([name,value])=>{const input=document.createElement('input');input.type='hidden';input.name=name;input.value=value;form.appendChild(input);});
    document.body.appendChild(form);
    return new Promise((resolve,reject)=>{
      const cleanup=()=>{window.removeEventListener('message',onMessage);clearTimeout(timer);form.remove();frame.remove();};
      const onMessage=event=>{let host='';try{host=new URL(event.origin).hostname;}catch(_){}const trustedOrigin=event.origin==='https://script.google.com'||host.endsWith('.googleusercontent.com')||(event.origin==='null'&&event.data?.bridgeNonce===bridgeNonce);if(!trustedOrigin||!event.data||event.data.requestId!==requestId||event.data.bridgeNonce!==bridgeNonce)return;cleanup();const data=event.data.result;if(!data?.ok)return reject(new Error(data?.error||'APIエラー'));resolve(data.data);};
      const timer=setTimeout(()=>{cleanup();reject(new Error('Apps Script APIがタイムアウトしました。'));},30000);
      window.addEventListener('message',onMessage);form.submit();
    });
  }
  const statusClass=s=>({'未送信':'unsent','送信待ち':'unsent','送信中':'sending','送信済み':'sent','再送済み':'sent','送信失敗':'failed','URLアクセス済み':'accessed','DL済':'downloaded','期限切れ':'expired','無効化':'disabled'}[s]||'unsent');
  const displayDlStatus=s=>{
    const status=String(s||'');
    if(['送信済み','再送済み'].includes(status))return '未アクセス';
    if(!status||['未送信','送信待ち','送信中','送信失敗','送信前確認'].includes(status))return '送信前';
    return status;
  };
  function cards(values){return Object.entries(values).map(([label,value])=>`<div class="summary-card"><strong>${esc(value)}</strong><span>${esc(label)}</span></div>`).join('');}
  function reconcile(){state.invoices=C.matchPartners(state.invoices,state.partners);renderCreate();}
  async function onInvoiceCsv(file){try{const decoded=await C.decodeCsvFile(file);state.invoices=C.parseInvoiceRows(C.parseCsv(decoded.text));activateStep(1);reconcile();$('#invoiceImportSummary').innerHTML=cards({'読込件数':state.invoices.length,'文字コード':decoded.encoding,'10円丸め調整':state.invoices.filter(x=>x.roundingAdjusted).length,'照合済み':state.invoices.filter(x=>x.partner).length});$('#invoiceImportSummary').classList.remove('hidden');activateStep(2);alert(`${state.invoices.length}件を読み込みました。送信は行っていません。`,'success');}catch(e){alert(e.message,'error');}}
  async function onPartnerCsv(file){try{const decoded=await C.decodeCsvFile(file);state.partners=C.parsePartners(C.parseCsv(decoded.text));persistPartners();renderPartners();renderPartnerOptions();reconcile();await safeApi('importPartners',{partners:state.partners});alert(`${state.partners.length}件の取引先を読み込みました（${decoded.encoding}）。`,'success');}catch(e){alert(e.message,'error');}}
  function loadDemoPartners(){try{const byCode=new Map(state.partners.map(p=>[p['顧客コード'],p]));C.DEMO_PARTNERS.forEach(p=>byCode.set(p['顧客コード'],p));state.partners=[...byCode.values()];persistPartners();renderPartners();renderPartnerOptions();reconcile();alert('指定のメールアドレスでダミー取引先4件を表示しました。','success');}catch(e){alert(e.message,'error');}}
  function openPartnerForm(code=''){const form=$('#partnerForm'),partner=state.partners.find(item=>String(item['顧客コード'])===String(code));form.reset();state.editingPartnerCode=partner?String(partner['顧客コード']):null;$('#partnerDialogTitle').textContent=partner?'取引先を編集':'取引先を個別入力';$('#savePartnerButton').textContent=partner?'変更を保存':'取引先マスタへ登録';form.elements.customerCode.readOnly=!!partner;if(partner){form.elements.customerCode.value=partner['顧客コード'];form.elements.name.value=partner['名称'];form.elements.kana.value=partner['名称(カナ)'];form.elements.honorific.value=partner['敬称']||'様';form.elements.postal.value=partner['郵便番号'];form.elements.prefecture.value=partner['都道府県'];form.elements.address1.value=partner['住所1'];form.elements.address2.value=partner['住所2'];form.elements.phone.value=partner['電話番号'];form.elements.email.value=partner['メールアドレス'];form.elements.cc.value=partner['CCメールアドレス'];form.elements.memo.value=partner['メモ'];}else form.elements.prefecture.value='愛知県';$('#postalLookupStatus').textContent='7桁入力すると住所を自動入力します。';$('#partnerDialog').showModal();}
  function goToPartnerCreate(){showView('partners');openPartnerForm();}
  async function savePartner(event){event.preventDefault();try{const values=Object.fromEntries(new FormData(event.currentTarget).entries()),code=String(values.customerCode||'').trim(),email=String(values.email||'').trim();if(!code)throw new Error('顧客コードを入力してください。');if(!String(values.name||'').trim())throw new Error('名称を入力してください。');if(!C.validateEmail(email))throw new Error('メールアドレスの形式が不正です。');if(values.cc&&!C.validateEmail(values.cc))throw new Error('CCメールアドレスの形式が不正です。');const partner=Object.fromEntries(C.PARTNER_HEADERS.map(header=>[header,'']));Object.assign(partner,{'顧客コード':code,'名称':String(values.name).trim(),'名称(カナ)':String(values.kana||'').trim(),'敬称':values.honorific||'様','郵便番号':String(values.postal||'').trim(),'都道府県':String(values.prefecture||'').trim(),'住所1':String(values.address1||'').trim(),'住所2':String(values.address2||'').trim(),'電話番号':String(values.phone||'').trim(),'メールアドレス':email,'CCメールアドレス':String(values.cc||'').trim(),'メモ':String(values.memo||'').trim()});const existing=state.partners.findIndex(item=>String(item['顧客コード'])===String(state.editingPartnerCode||code));if(existing>=0)state.partners[existing]=partner;else state.partners.push(partner);persistPartners();renderPartners();renderPartnerOptions();reconcile();await safeApi('importPartners',{partners:state.partners});$('#partnerDialog').close();state.editingPartnerCode=null;alert(`${partner['名称']}を取引先マスタへ${existing>=0?'更新':'登録'}しました。`,'success');}catch(e){alert(e.message,'error');}}
  function openPartnerDelete(code){const partner=state.partners.find(item=>String(item['顧客コード'])===String(code));if(!partner)return;state.pendingDeletePartnerCode=String(code);$('#deletePartnerTarget').textContent=`${partner['顧客コード']}　${partner['名称']}`;$('#deletePartnerForm').reset();$('#confirmDeletePartner').disabled=true;$('#deletePartnerDialog').showModal();}
  function updateDeleteConfirmation(){const code=String($('#deletePartnerCodeInput').value||'').trim(),checked=$('#deletePartnerCheck').checked;$('#confirmDeletePartner').disabled=code!==String(state.pendingDeletePartnerCode)||!checked;}
  async function deletePartner(event){event.preventDefault();const code=state.pendingDeletePartnerCode,partner=state.partners.find(item=>String(item['顧客コード'])===String(code)),button=$('#confirmDeletePartner');if(!partner||button.disabled)return;button.disabled=true;button.textContent='削除しています…';try{await api('deletePartner',{customerCode:code});state.partners=state.partners.filter(item=>String(item['顧客コード'])!==String(code));persistPartners();renderPartners();renderPartnerOptions();reconcile();$('#deletePartnerDialog').close();state.pendingDeletePartnerCode=null;alert(`${partner['名称']}を取引先マスタから削除しました。`,'success');}catch(e){alert(e.message,'error');}finally{button.disabled=false;button.textContent='本当に削除する';}}
  async function lookupPostal(){const form=$('#partnerForm'),digits=String(form.elements.postal.value||'').replace(/\D/g,'');if(digits.length!==7){$('#postalLookupStatus').textContent='7桁入力すると住所を自動入力します。';return;}const request=++state.postalRequest;$('#postalLookupStatus').textContent='住所を検索しています…';try{const response=await fetch(`https://zipcloud.ibsnet.co.jp/api/search?zipcode=${encodeURIComponent(digits)}`);if(!response.ok)throw new Error('住所検索に失敗しました。');const data=await response.json();if(request!==state.postalRequest)return;const address=data?.results?.[0];if(!address)throw new Error('該当する住所が見つかりません。');form.elements.postal.value=`${digits.slice(0,3)}-${digits.slice(3)}`;form.elements.prefecture.value=address.address1||'';form.elements.address1.value=`${address.address2||''}${address.address3||''}`;$('#postalLookupStatus').textContent='都道府県と住所1を自動入力しました。';}catch(e){if(request===state.postalRequest)$('#postalLookupStatus').textContent=e.message;}}
  function openStudentImport(){const form=$('#studentSearchForm');form.reset();state.studentCandidate=null;$('#studentSearchResult').classList.add('hidden');$('#studentSearchStatus').textContent='';$('#importStudentPartner').disabled=true;$('#studentImportDialog').showModal();}
  async function searchStudent(event){event.preventDefault();const input=event.currentTarget.elements.studentCode,code=C.normalizeStudentCode(input.value),button=$('#searchStudent');input.value=code;if(!code)return alert('生徒コードを入力してください。');if(!/^[A-Za-z0-9]+$/.test(code)){input.focus();$('#studentSearchStatus').textContent='生徒コードは半角英数で入力してください。';return;}button.disabled=true;$('#studentSearchStatus').textContent='生徒マスタを検索しています…';$('#studentSearchResult').classList.add('hidden');$('#importStudentPartner').disabled=true;state.studentCandidate=null;try{const student=await api('findStudentForPartner',{studentCode:code});state.studentCandidate=student;$('#studentResultCode').textContent=student.studentCode;$('#studentResultName').textContent=student.name;$('#studentResultGrade').textContent=student.grade||'未登録';$('#studentSearchResult').classList.remove('hidden');$('#studentSearchStatus').textContent='氏名と学年を確認し、対象の生徒を選択してください。';}catch(e){$('#studentSearchStatus').textContent=e.message;}finally{button.disabled=false;}}
  async function importStudentPartner(){if(!state.studentCandidate||!$('#studentSearchForm').elements.studentChoice.checked)return alert('取り込む生徒を選択してください。');try{const partner=C.studentToPartner(state.studentCandidate);if(!C.validateEmail(partner['メールアドレス']))throw new Error('生徒マスタのメールアドレスが未登録または不正です。');const existing=state.partners.findIndex(item=>String(item['顧客コード'])===partner['顧客コード']);if(existing>=0)state.partners[existing]=partner;else state.partners.push(partner);persistPartners();renderPartners();renderPartnerOptions();reconcile();await safeApi('importPartners',{partners:state.partners});$('#studentImportDialog').close();alert(`${partner['名称']}を取引先マスタへ${existing>=0?'更新':'登録'}しました。`,'success');}catch(e){alert(e.message,'error');}}
  function renderCreate(){const tbody=$('#createTable tbody');if(!state.invoices.length){tbody.innerHTML='<tr class="empty"><td colspan="11">請求書CSVを読み込むか、個別作成で1件追加してください。</td></tr>';$('#addToSend').disabled=true;return;}tbody.innerHTML=state.invoices.map((x,i)=>`<tr><td><input type="checkbox" data-create-select="${i}"></td><td>${esc(x.invoiceNumber)}</td><td>${esc(x.customerCode)}</td><td>${esc(x.partnerName)} ${esc(x.honorific)}</td><td>${esc(x.subject)}</td><td class="num">${C.formatYen(x.total)}</td><td>${esc(x.email)}</td><td>${esc(x.cc)}</td><td><span class="status ${x.pdfStatus==='PDF作成済み'?'sent':'unsent'}">${esc(x.pdfStatus==='PDF作成済み'?'PDF作成済み':'送信時に自動作成')}</span></td><td>${x.warnings.length?`<span class="warning-text">${esc(x.warnings.join('／'))}</span>`:'なし'}</td><td><button class="button secondary" data-preview="${i}">表示</button></td></tr>`).join('');$('#addToSend').disabled=false;tbody.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>previewInvoice(Number(b.dataset.preview)));}
  function renderPartners(){const tbody=$('#partnerTable tbody');tbody.innerHTML=state.partners.length?state.partners.map(p=>`<tr><td>${esc(p['顧客コード'])}</td><td>${esc(p['名称'])}</td><td>${esc(p['敬称'])}</td><td>${esc(p['郵便番号'])}</td><td>${esc(p['都道府県']+p['住所1']+p['住所2'])}</td><td>${esc(p['電話番号'])}</td><td>${esc(p['メールアドレス'])}</td><td>${esc(p['CCメールアドレス'])}</td><td>${esc(p['メモ'])}</td><td><button class="button secondary compact" type="button" data-edit-partner="${esc(p['顧客コード'])}">編集</button> <button class="button compact-danger" type="button" data-delete-partner="${esc(p['顧客コード'])}">削除</button></td></tr>`).join(''):'<tr class="empty"><td colspan="10">取引先CSVを読み込むか、個別入力してください。</td></tr>';tbody.querySelectorAll('[data-edit-partner]').forEach(button=>button.onclick=()=>openPartnerForm(button.dataset.editPartner));tbody.querySelectorAll('[data-delete-partner]').forEach(button=>button.onclick=()=>openPartnerDelete(button.dataset.deletePartner));}
  function singleDetailRows(){return $$('#singleDetailBody tr').map(row=>({name:row.querySelector('[name="detailName"]').value,unitPrice:row.querySelector('[name="detailUnitPrice"]').value,quantity:row.querySelector('[name="detailQuantity"]').value,unit:row.querySelector('[name="detailUnit"]').value,taxRate:row.querySelector('[name="detailTaxRate"]').value}));}
  function updateSingleTotals(){const rows=singleDetailRows();const subtotal=rows.reduce((sum,row)=>sum+Math.round(Number(row.unitPrice||0)*Number(row.quantity||0)),0);const sourceTax=rows.reduce((sum,row)=>{const amount=Math.round(Number(row.unitPrice||0)*Number(row.quantity||0));return sum+Math.round(amount*Number(row.taxRate||0)/100);},0);const total=C.roundToNearest10(subtotal+sourceTax);$('#singleSubtotal').textContent=C.formatYen(subtotal);$('#singleTax').textContent=C.formatYen(total-subtotal);$('#singleTotal').textContent=C.formatYen(total);$$('#singleDetailBody tr').forEach((row,index)=>{const detail=rows[index];row.querySelector('[data-detail-amount]').textContent=C.formatYen(Math.round(Number(detail.unitPrice||0)*Number(detail.quantity||0)));});}
  function addSingleDetail(data={}){const row=document.createElement('tr');row.innerHTML=`<td><input name="detailName" value="${esc(data.name||'')}" placeholder="例：授業料・割引" required></td><td><input name="detailUnitPrice" type="number" step="1" value="${esc(data.unitPrice??'')}" placeholder="例：25000／割引は-10000" required></td><td><input name="detailQuantity" type="number" min="0.01" step="0.01" value="${esc(data.quantity??1)}" required></td><td><input name="detailUnit" value="${esc(data.unit||'')}" placeholder="回・月"></td><td><select name="detailTaxRate"><option value="10" ${Number(data.taxRate??10)===10?'selected':''}>10%</option><option value="8" ${Number(data.taxRate)===8?'selected':''}>8%</option><option value="0" ${Number(data.taxRate)===0?'selected':''}>0%</option></select></td><td class="num" data-detail-amount>0円</td><td><button class="remove-detail" type="button" aria-label="明細を削除">削除</button></td>`;row.querySelectorAll('input,select').forEach(input=>input.addEventListener('input',updateSingleTotals));row.querySelector('.remove-detail').onclick=()=>{if($$('#singleDetailBody tr').length===1)return alert('明細は1行以上必要です。');row.remove();updateSingleTotals();};$('#singleDetailBody').appendChild(row);updateSingleTotals();}
  function resetSingleForm(){const form=$('#singleInvoiceForm');form.reset();$('#singleDetailBody').innerHTML='';addSingleDetail();renderPartnerOptions();setSingleDefaults(true);}
  function validateSingleInvoiceForPreview(){
    const form=$('#singleInvoiceForm'),missing=[],mark=(element,label)=>{if(!element||String(element.value||'').trim())return;element.classList.add('field-missing');missing.push(label);};
    $$('#singleInvoiceForm .field-missing').forEach(element=>element.classList.remove('field-missing'));
    mark(form.elements.partnerCode,'取引先');mark(form.elements.invoiceNumber,'請求書番号');mark(form.elements.subject,'件名');mark(form.elements.invoiceDate,'請求日');mark(form.elements.dueDate,'支払期限');
    $$('#singleDetailBody tr').forEach((row,index)=>{const number=index+1,name=row.querySelector('[name="detailName"]'),unitPrice=row.querySelector('[name="detailUnitPrice"]'),quantity=row.querySelector('[name="detailQuantity"]');mark(name,`明細${number}の品目`);if(!String(unitPrice.value||'').trim()||!Number.isFinite(Number(unitPrice.value))){unitPrice.classList.add('field-missing');missing.push(`明細${number}の単価`);}if(!String(quantity.value||'').trim()||Number(quantity.value)<=0){quantity.classList.add('field-missing');missing.push(`明細${number}の数量`);}});
    if(!missing.length)return true;
    const first=$('#singleInvoiceForm .field-missing');if(first)first.focus();
    alert(`プレビューを表示できません。入力が必要な項目：${missing.join('、')}`,'error');
    return false;
  }
  function currentSingleInvoice(){const form=$('#singleInvoiceForm'),values=Object.fromEntries(new FormData(form).entries()),partner=state.partners.find(item=>item['顧客コード']===values.partnerCode);return C.matchPartners([C.buildManualInvoice(values,singleDetailRows(),partner)],state.partners)[0];}
  async function addSingleInvoice(event){event.preventDefault();if(!validateSingleInvoiceForPreview())return;const button=event.submitter||event.currentTarget.querySelector('[type="submit"]'),originalText=button?.textContent||'';if(button){button.disabled=true;button.textContent='保存しています…';}try{const invoice=currentSingleInvoice();if(state.invoices.some(item=>item.invoiceNumber===invoice.invoiceNumber))throw new Error('同じ請求書番号が発行リストにあります。');invoice.paymentStatus='未入金';invoice.createdAt=localIso(new Date());await api('saveInvoiceData',{invoice});state.invoices.push(invoice);state.selectedInvoiceNumber=invoice.invoiceNumber;renderCreate();renderInvoices();$('#invoiceImportSummary').innerHTML=cards({'作成方法':'個別作成','追加件数':1,'発行リスト':state.invoices.length,'請求金額':C.formatYen(invoice.total)});$('#invoiceImportSummary').classList.remove('hidden');activateStep(4);resetSingleForm();showView('invoices');alert(`${invoice.invoiceNumber} ${invoice.partnerName}の請求書を台帳へ保存しました。`,'success');}catch(e){alert(`請求書は保存されていません。${e.message}`,'error');}finally{if(button){button.disabled=false;button.textContent=originalText;}}}
  const invoiceSortValue=invoice=>{const date=Date.parse(String(invoice.createdAt||invoice.invoiceDate||'').replace(/\//g,'-'));return Number.isFinite(date)?date:0;};
  const sortedInvoices=()=>state.invoices.slice().sort((a,b)=>invoiceSortValue(b)-invoiceSortValue(a)||String(b.invoiceNumber).localeCompare(String(a.invoiceNumber),'ja'));
  const selectedInvoice=()=>state.invoices.find(invoice=>String(invoice.invoiceNumber)===String(state.selectedInvoiceNumber));
  const paymentClass=status=>status==='入金済'?'paid':status==='未設定'?'unset':'unpaid';
  const inputDate=value=>{const match=String(value||'').match(/^(\d{4})[\/-](\d{1,2})[\/-](\d{1,2})/);return match?`${match[1]}-${match[2].padStart(2,'0')}-${match[3].padStart(2,'0')}`:'';};
  const normalizeSearch=value=>String(value??'').normalize('NFKC').toLocaleLowerCase('ja').replace(/[\s　]+/g,'');
  function invoiceSearchText(invoice){return normalizeSearch([invoice.invoiceNumber,invoice.customerCode,invoice.partnerName,invoice.honorific,invoice.subject,invoice.memo,invoice.tags,invoice.note,invoice.email,invoice.cc,invoice.postal,invoice.prefecture,invoice.address1,invoice.address2,invoice.paymentStatus,invoice.sendStatus,invoice.invoiceDate,invoice.dueDate,invoice.createdAt,invoice.updatedAt,...(invoice.details||[]).flatMap(detail=>[detail.name,detail.itemCode,detail.unit,detail.unitPrice,detail.quantity,detail.amount,detail.taxRate])].join(' '));}
  function filteredInvoices(){const {dateField,from,to,query}=state.invoiceFilters,needle=normalizeSearch(query);return sortedInvoices().filter(invoice=>{const date=inputDate(invoice[dateField]);if((from||to)&&!date)return false;if(from&&date<from)return false;if(to&&date>to)return false;return !needle||invoiceSearchText(invoice).includes(needle);});}
  function updateInvoiceFilters(){state.invoiceFilters={dateField:$('#invoiceDateField').value,from:$('#invoiceDateFrom').value,to:$('#invoiceDateTo').value,query:$('#invoiceFreeSearch').value};renderInvoices();}
  function clearInvoiceFilters(){state.invoiceFilters={dateField:'createdAt',from:'',to:'',query:''};$('#invoiceDateField').value='createdAt';$('#invoiceDateFrom').value='';$('#invoiceDateTo').value='';$('#invoiceFreeSearch').value='';renderInvoices();}
  function renderInvoices(){
    const ordered=filteredInvoices(),filtered=ordered.length!==state.invoices.length||state.invoiceFilters.from||state.invoiceFilters.to||state.invoiceFilters.query;$('#invoiceListCount').textContent=filtered?`該当 ${ordered.length}件／全${state.invoices.length}件`:`${ordered.length}件`;
    if(ordered.length&&!ordered.some(invoice=>String(invoice.invoiceNumber)===String(state.selectedInvoiceNumber)))state.selectedInvoiceNumber=String(ordered[0].invoiceNumber);
    if(!ordered.length)state.selectedInvoiceNumber='';
    $('#invoiceList').innerHTML=ordered.length?ordered.map(invoice=>{const payment=invoice.paymentStatus||'未入金';return `<button class="invoice-list-item ${String(invoice.invoiceNumber)===String(state.selectedInvoiceNumber)?'active':''}" type="button" data-invoice-select="${esc(invoice.invoiceNumber)}"><span class="invoice-list-meta"><span>${esc(invoice.createdAt||invoice.invoiceDate||'')}</span><span>No. ${esc(invoice.invoiceNumber)}</span></span><span class="invoice-list-name">${esc(invoice.partnerName||'取引先未設定')}</span><span class="invoice-list-subject">${esc(invoice.subject||'件名未設定')}</span><span class="invoice-list-statuses"><span class="payment-pill ${paymentClass(payment)}">${esc(payment)}</span><span class="status ${statusClass(invoice.sendStatus)}">${esc(invoice.sendStatus||'未送信')}</span><strong class="invoice-list-amount">${C.formatYen(invoice.total)}</strong></span></button>`;}).join(''):`<p class="invoice-list-empty">${state.invoices.length?'検索条件に一致する請求書がありません。':'請求書がありません。'}</p>`;
    $$('[data-invoice-select]').forEach(button=>button.onclick=()=>{state.selectedInvoiceNumber=button.dataset.invoiceSelect;renderInvoices();});renderInvoiceDetail(ordered.find(invoice=>String(invoice.invoiceNumber)===String(state.selectedInvoiceNumber)));
  }
  function renderInvoiceDetail(invoice){
    const panel=$('#invoiceDetailPanel');if(!invoice){panel.innerHTML='<div class="invoice-detail-empty">請求書を作成すると、ここにプレビューが表示されます。</div>';return;}
    const payment=invoice.paymentStatus||'未入金',historyRows=state.history.filter(item=>String(item.invoiceNumber)===String(invoice.invoiceNumber));
    panel.innerHTML=`<div class="invoice-detail-card"><div class="invoice-detail-top"><div class="invoice-detail-title-row"><div><h2>${esc(invoice.partnerName)} ${esc(invoice.honorific||'様')}</h2><p class="invoice-detail-meta">作成日：${esc(invoice.createdAt||invoice.invoiceDate||'―')}　　請求書番号：${esc(invoice.invoiceNumber)}</p></div><details id="selectedPaymentStatus" class="payment-dropdown" data-status="${esc(payment)}"><summary aria-label="入金状態">${esc(payment)}</summary><div class="payment-dropdown-menu" role="menu"><button type="button" data-payment-value="未設定">未設定</button><button type="button" data-payment-value="未入金">未入金</button><button type="button" data-payment-value="入金済">入金済</button></div></details></div><dl class="invoice-detail-fields"><dt>メモ</dt><dd>${esc(invoice.memo||'―')}</dd><dt>タグ</dt><dd>${invoice.tags?`<span class="campus-tag">${esc(invoice.tags)}</span>`:'―'}</dd></dl><div class="invoice-detail-actions"><div class="invoice-edit-actions"><button class="button secondary" data-invoice-action="edit">編集</button><button class="button secondary" data-invoice-action="duplicate">複製／変換</button><button class="button compact-danger" data-invoice-action="delete">削除</button></div><div class="invoice-output-actions"><button class="button mail-button" data-invoice-action="mail">メール</button><button class="button primary" data-invoice-action="pdf">PDF／印刷</button></div></div></div></div><div class="invoice-tabs"><button class="invoice-tab ${state.invoiceDetailTab==='preview'?'active':''}" data-invoice-tab="preview">プレビュー</button><button class="invoice-tab ${state.invoiceDetailTab==='history'?'active':''}" data-invoice-tab="history">履歴</button></div><div class="invoice-tab-panel">${state.invoiceDetailTab==='history'?selectedHistoryHtml(historyRows):`<div class="invoice-inline-preview">${P.pageHtml(invoice)}</div>`}</div>`;
    $$('[data-payment-value]').forEach(button=>button.onclick=()=>updatePaymentStatus(invoice,button.dataset.paymentValue));$$('[data-invoice-action]').forEach(button=>button.onclick=()=>invoiceAction(button.dataset.invoiceAction,invoice));$$('[data-invoice-tab]').forEach(button=>button.onclick=()=>{state.invoiceDetailTab=button.dataset.invoiceTab;renderInvoiceDetail(invoice);});
  }
  function selectedHistoryHtml(rows){return rows.length?`<table class="selected-history"><thead><tr><th>更新日時</th><th>内容</th><th>送信状態</th><th>取得状態</th></tr></thead><tbody>${rows.map(item=>`<tr><td>${esc(item.timestamp)}</td><td>請求書【No ${esc(item.invoiceNumber)}】の${esc(item.action)}</td><td>${esc(item.sendStatus)}</td><td>${esc(item.urlStatus)}</td></tr>`).join('')}</tbody></table>`:'<p class="invoice-list-empty">この請求書の履歴はまだありません。</p>';}
  async function updatePaymentStatus(invoice,value){const before=invoice.paymentStatus||'未入金';invoice.paymentStatus=value;renderInvoices();try{await api('updatePaymentStatus',{invoiceNumber:invoice.invoiceNumber,paymentStatus:value});alert(`入金状態を「${value}」に変更しました。`,'success');}catch(e){invoice.paymentStatus=before;renderInvoices();alert(e.message,'error');}}
  function invoiceAction(action,invoice){if(action==='edit')return openInvoiceEdit(invoice);if(action==='duplicate')return duplicateInvoice(invoice);if(action==='delete')return openInvoiceDelete(invoice);if(action==='mail')return openInvoiceMail(invoice);if(action==='pdf')return openInvoicePdf(invoice);}
  function openInvoiceMail(invoice){state.preview=invoice;const form=$('#mailForm'),settings={senderName:form.elements.senderName.value||'個別指導ステップ【請求書】',replyTo:form.elements.replyTo.value||'',subject:form.elements.subject.value||'【請求書】送付のご案内（個別指導ステップから）',body:form.elements.body.value||'',testRecipient:form.elements.testRecipient.value||''};$('#mailInvoiceNumber').textContent=invoice.invoiceNumber;$('#mailTo').textContent=settings.testRecipient?`${settings.testRecipient}（テスト送信先／本来の宛先：${invoice.email}）`:invoice.email;$('#mailCc').textContent=invoice.cc||'なし';$('#mailSender').textContent=settings.senderName;$('#mailReplyTo').textContent=settings.replyTo||'なし';$('#mailSubject').value=settings.subject;$('#mailBody').value=C.renderTemplate(settings.body,{'取引先名':invoice.partnerName,'敬称':invoice.honorific||'様','有効日数':form.elements.validDays.value||45,'ダウンロードURL':'（送信時にCloudflareのURLを発行します）'});const resend=C.isSentStatus(invoice.sendStatus);$('#confirmInvoiceMail').textContent=resend?'この内容で再送':'この内容で送信';const status=$('#invoiceMailStatus');status.textContent='';status.className='mail-submit-status hidden';$('#invoiceMailDialog').showModal();}
  async function confirmInvoiceMail(){const invoice=state.preview;if(!invoice)return;const button=$('#confirmInvoiceMail'),resend=C.isSentStatus(invoice.sendStatus),idleText=resend?'この内容で再送':'この内容で送信',status=$('#invoiceMailStatus');button.disabled=true;button.textContent='保存を確認しています…';status.textContent='請求書の台帳保存を確認しています。';status.className='mail-submit-status working';try{await api('saveInvoiceData',{invoice});button.textContent='PDFを準備しています…';status.textContent='請求書PDFを準備しています。';await ensurePdfsForSend([invoice]);button.textContent='送信を受け付けています…';status.textContent='メール送信を受け付けています。';await api('enqueueSend',{invoiceNumbers:[invoice.invoiceNumber],testMode:true,resend,newToken:true});$('#invoiceMailDialog').close();await refreshAll(false);alert(resend?'再送を受け付けました。送信状態は一覧で確認できます。':'送信を受け付けました。送信状態は一覧で確認できます。','success');}catch(e){status.textContent=`送信できませんでした：${e.message}`;status.className='mail-submit-status error';alert(`送信できませんでした：${e.message}`,'error');}finally{button.disabled=false;button.textContent=idleText;}}
  function openInvoicePdf(invoice){state.preview=invoice;$('#pdfInvoiceTarget').textContent=`${invoice.partnerName} 様　請求書 No. ${invoice.invoiceNumber}`;$('#invoicePdfDialog').showModal();}
  function editDetailRows(){return $$('#editInvoiceDetailBody tr').map(row=>({name:row.querySelector('[name="editDetailName"]').value,unitPrice:Number(row.querySelector('[name="editDetailUnitPrice"]').value||0),quantity:Number(row.querySelector('[name="editDetailQuantity"]').value||0),unit:row.querySelector('[name="editDetailUnit"]').value,taxRate:Number(row.querySelector('[name="editDetailTaxRate"]').value||0)}));}
  function updateEditTotals(){const rows=editDetailRows(),subtotal=rows.reduce((sum,row)=>sum+Math.round(row.unitPrice*row.quantity),0),sourceTax=rows.reduce((sum,row)=>sum+Math.round(row.unitPrice*row.quantity*row.taxRate/100),0),total=C.roundToNearest10(subtotal+sourceTax);$('#editInvoiceSubtotal').textContent=C.formatYen(subtotal);$('#editInvoiceTax').textContent=C.formatYen(total-subtotal);$('#editInvoiceTotal').textContent=C.formatYen(total);$$('#editInvoiceDetailBody tr').forEach((row,index)=>row.querySelector('[data-edit-detail-amount]').textContent=C.formatYen(Math.round(rows[index].unitPrice*rows[index].quantity)));}
  function addEditDetail(data={}){const row=document.createElement('tr'),tax=Number(String(data.taxRate??10).replace('%',''));row.innerHTML=`<td><input name="editDetailName" value="${esc(data.name||'')}" required></td><td><input name="editDetailUnitPrice" type="number" step="1" value="${esc(data.unitPrice??'')}" required></td><td><input name="editDetailQuantity" type="number" min="0.01" step="0.01" value="${esc(data.quantity??1)}" required></td><td><input name="editDetailUnit" value="${esc(data.unit||'')}"></td><td><select name="editDetailTaxRate"><option value="10" ${tax===10?'selected':''}>10%</option><option value="8" ${tax===8?'selected':''}>8%</option><option value="0" ${tax===0?'selected':''}>0%</option></select></td><td data-edit-detail-amount>0円</td><td><button class="remove-detail" type="button">削除</button></td>`;row.querySelectorAll('input,select').forEach(element=>element.oninput=updateEditTotals);row.querySelector('.remove-detail').onclick=()=>{if($$('#editInvoiceDetailBody tr').length<2)return alert('明細は1行以上必要です。');row.remove();updateEditTotals();};$('#editInvoiceDetailBody').appendChild(row);updateEditTotals();}
  function openInvoiceEdit(invoice){state.preview=invoice;const form=$('#editInvoiceForm');form.reset();form.elements.partnerName.value=invoice.partnerName||'';form.elements.invoiceNumber.value=invoice.invoiceNumber;form.elements.subject.value=invoice.subject||'';form.elements.invoiceDate.value=inputDate(invoice.invoiceDate);form.elements.dueDate.value=inputDate(invoice.dueDate);form.elements.memo.value=invoice.memo||'';form.elements.tags.value=invoice.tags||'';form.elements.paymentStatus.value=invoice.paymentStatus||'未入金';form.elements.note.value=invoice.note||'';$('#editInvoiceDetailBody').innerHTML='';(invoice.details?.length?invoice.details:[{name:'請求内容',unitPrice:invoice.subtotal||0,quantity:1,unit:'',taxRate:10}]).forEach(addEditDetail);$('#editInvoiceDialog').showModal();}
  async function saveInvoiceEdit(event){event.preventDefault();const original=state.preview;if(!original)return;try{const values=Object.fromEntries(new FormData(event.currentTarget).entries()),rows=editDetailRows();if(!rows.length||rows.some(row=>!row.name||!Number.isFinite(row.unitPrice)||row.quantity<=0))throw new Error('請求明細を正しく入力してください。');const details=rows.map(row=>{const amount=Math.round(row.unitPrice*row.quantity);return {deliveryDate:'',name:row.name,itemCode:'',unitPrice:row.unitPrice,quantity:row.quantity,unit:row.unit,deliveryNumber:'',detail:'',amount,withholding:'含まない',taxRate:`${row.taxRate}%`};}),subtotal=details.reduce((sum,row)=>sum+row.amount,0),sourceTax=rows.reduce((sum,row)=>sum+Math.round(row.unitPrice*row.quantity*row.taxRate/100),0),total=C.roundToNearest10(subtotal+sourceTax),updated={...original,...values,details,subtotal,sourceTax,sourceTotal:subtotal+sourceTax,tax:total-subtotal,total,pdfStatus:'未作成',pdfFileId:'',pdfFileName:'',updatedAt:new Date().toISOString()};await api('saveInvoiceData',{invoice:updated});const index=state.invoices.findIndex(item=>String(item.invoiceNumber)===String(updated.invoiceNumber));state.invoices[index]=updated;state.preview=updated;$('#editInvoiceDialog').close();renderCreate();renderInvoices();alert('請求書の変更を保存しました。PDFは次回の送信・ダウンロード時に作り直されます。','success');}catch(e){alert(e.message,'error');}}
  async function duplicateInvoice(invoice){try{const today=localIso(new Date()),copy=JSON.parse(JSON.stringify(invoice));copy.invoiceNumber=C.nextInvoiceNumber(today,state.invoices);copy.invoiceDate=today;copy.dueDate=plusDays(today,21);copy.createdAt=today;copy.updatedAt=new Date().toISOString();copy.paymentStatus='未入金';copy.pdfStatus='未作成';copy.pdfFileId='';copy.pdfFileName='';copy.sendStatus='未送信';copy.sentAt='';copy.dlStatus='未取得';copy.downloadedAt='';copy.expiresAt='';await api('saveInvoiceData',{invoice:copy});state.invoices.push(copy);state.selectedInvoiceNumber=copy.invoiceNumber;renderCreate();renderInvoices();alert(`請求書を複製しました。新しい請求書番号は ${copy.invoiceNumber} です。`,'success');openInvoiceEdit(copy);}catch(e){alert(`複製できませんでした：${e.message}`,'error');}}
  function openInvoiceDelete(invoice){state.pendingDeleteInvoiceNumber=String(invoice.invoiceNumber);$('#deleteInvoiceTarget').textContent=`${invoice.partnerName}　No. ${invoice.invoiceNumber}`;$('#deleteInvoiceForm').reset();$('#confirmDeleteInvoice').disabled=true;$('#deleteInvoiceDialog').showModal();}
  function updateInvoiceDeleteConfirmation(){const matches=String($('#deleteInvoiceNumberInput').value||'').trim()===String(state.pendingDeleteInvoiceNumber),checked=$('#deleteInvoiceCheck').checked;$('#confirmDeleteInvoice').disabled=!matches||!checked;}
  async function deleteInvoice(event){event.preventDefault();const number=state.pendingDeleteInvoiceNumber,button=$('#confirmDeleteInvoice');if(!number||button.disabled)return;button.disabled=true;button.textContent='削除しています…';try{await api('deleteInvoice',{invoiceNumber:number});state.invoices=state.invoices.filter(invoice=>String(invoice.invoiceNumber)!==String(number));state.selectedInvoiceNumber='';$('#deleteInvoiceDialog').close();renderCreate();renderInvoices();alert(`請求書 No. ${number} を削除しました。`,'success');}catch(e){alert(e.message,'error');}finally{button.disabled=false;button.textContent='本当に削除する';}}
  function renderHistory(){const tbody=$('#historyTable tbody');tbody.innerHTML=state.history.length?state.history.map(x=>`<tr><td>${esc(x.timestamp)}</td><td>${esc(x.action)}</td><td>${esc(x.invoiceNumber)}</td><td>${esc(x.name)}</td><td>${esc(x.deliveryId)}</td><td>${esc(x.sendStatus)}</td><td>${esc(x.urlStatus)}</td><td>${esc(x.result||x.error)}</td></tr>`).join(''):'<tr class="empty"><td colspan="8">履歴がありません。</td></tr>';}
  function showInvoicePreview(invoice){state.preview=invoice;$('#invoicePreviewHost').innerHTML=P.pageHtml(invoice,{preview:true});$('#previewDialog').showModal();activateStep(3);}
  function previewInvoice(index){showInvoicePreview(state.invoices[index]);}
  function previewSingleInvoice(){if(!validateSingleInvoiceForPreview())return;try{showInvoicePreview(currentSingleInvoice());}catch(e){alert(`プレビューを表示できません。${e.message}`,'error');}}
  function printPreview(){if(!state.preview)return alert('印刷する請求書がありません。');document.body.classList.add('printing-invoice');window.print();setTimeout(()=>document.body.classList.remove('printing-invoice'),500);}
  async function createPdf(inv,{save=false,preview=false}={}){const host=document.createElement('div');host.className='pdf-render-host';host.innerHTML=P.pageHtml(inv,{preview});document.body.appendChild(host);try{await new Promise(r=>setTimeout(r,300));const blob=await P.toBlob(host.querySelector('.invoice-page'));if(save){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${inv.invoiceNumber}_${inv.partnerName}${inv.honorific||'様'}${preview?'_プレビュー':''}.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}return blob;}finally{host.remove();}}
  function blobToBase64(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(blob);});}
  async function safeApi(action,payload){if(!state.settings.apiUrl)return null;return api(action,payload);}
  function selectedItems(){return [...state.selected].map(i=>state.invoices[i]).filter(Boolean);}
  async function ensurePdfsForSend(items){const pending=items.filter(item=>item&&item.pdfStatus!=='PDF作成済み');if(!pending.length)return;alert(`${pending.length}件の送信用PDFを自動作成しています。`,'success');for(const inv of pending){const blob=await createPdf(inv);const base64=await blobToBase64(blob);const result=await api('savePdf',{invoice:inv,pdfBase64:base64});inv.pdfStatus='PDF作成済み';inv.pdfFileId=result?.pdfFileId||'';inv.pdfFileName=result?.pdfFileName||`${inv.invoiceNumber}_${inv.partnerName}${inv.honorific||'様'}.pdf`;}renderCreate();renderInvoices();}
  async function openSendDialog(items){
    try{await ensurePdfsForSend(items);}catch(e){alert(`送信用PDFを作成できませんでした。${e.message}`,'error');return;}
    const groups=C.classifySendSelection(items);
    if(groups.resend.length)return openResendDialog(groups);
    const s=C.selectedSummary(items);
    $('#sendSummary').innerHTML=cards({'選択件数':s.selected,'送信可能':groups.unsent.length,'メール未登録':s.missingEmail,'メール形式不正':s.invalidEmail,'PDF未作成':s.missingPdf,'送信できない':groups.blocked.length});
    $('#confirmSend').textContent=`選択した${groups.unsent.length}件を送信`;
    $('#confirmSend').disabled=!groups.unsent.length;
    $('#sendDialog').showModal();
  }
  function openResendDialog(groups){
    state.pendingResend=groups;
    $('#resendSummary').innerHTML=cards({'選択件数':`${groups.selected.length}件`,'未送信件数':`${groups.unsent.length}件`,'再送対象件数':`${groups.resend.length}件`,'送信できない件数':`${groups.blocked.length}件`});
    $('#resendTableBody').innerHTML=groups.resend.map(x=>`<tr><td>${esc(x.invoiceNumber)}</td><td>${esc(x.partnerName)}</td><td>${esc(x.email)}</td><td>${esc(x.sentAt||'―')}</td><td><span class="status ${statusClass(x.dlStatus)}">${esc(x.dlStatus||'未取得')}</span></td></tr>`).join('');
    const button=$('#confirmResend');button.disabled=false;button.textContent='再送する';
    $('#resendDialog').showModal();
  }
  async function confirmSend(){
    const groups=C.classifySendSelection(selectedItems());
    if(groups.resend.length){$('#sendDialog').close();return openResendDialog(groups);}
    if(!groups.unsent.length)return;
    const button=$('#confirmSend');button.disabled=true;button.textContent='送信を受け付けています…';
    try{await api('enqueueSend',{invoiceNumbers:groups.unsent.map(x=>x.invoiceNumber),testMode:true,resend:false,newToken:true});$('#sendDialog').close();await refreshAll(false);alert('送信処理を実行しました。送信状態を更新しました。','success');}catch(e){alert(e.message,'error');}finally{button.disabled=false;button.textContent=`選択した${groups.unsent.length}件を送信`;}
  }
  async function confirmResend(){
    if(state.resendSubmitting||!state.pendingResend)return;
    state.resendSubmitting=true;
    const groups=state.pendingResend,button=$('#confirmResend');button.disabled=true;button.textContent='再送を受け付けています…';
    try{
      if(groups.unsent.length)await api('enqueueSend',{invoiceNumbers:groups.unsent.map(x=>x.invoiceNumber),testMode:true,resend:false,newToken:true});
      if(groups.resend.length)await api('enqueueSend',{invoiceNumbers:groups.resend.map(x=>x.invoiceNumber),testMode:true,resend:true,newToken:true});
      $('#resendDialog').close();await refreshAll(false);alert('初回送信と再送の処理を実行し、送信状態を更新しました。','success');state.pendingResend=null;
    }catch(e){alert(e.message,'error');button.disabled=false;button.textContent='再送する';}finally{state.resendSubmitting=false;}
  }
  function openDisableDialog(inv){state.pendingDisable=inv;$('#disableTarget').textContent=`請求書番号: ${inv.invoiceNumber}　顧客名: ${inv.partnerName}`;$('#disableDialog').showModal();}
  async function confirmDisable(){const inv=state.pendingDisable;if(!inv)return;const button=$('#confirmDisable');button.disabled=true;try{await api('disableDelivery',{invoiceNumber:inv.invoiceNumber});inv.sendStatus='無効化';renderInvoices();$('#disableDialog').close();state.pendingDisable=null;}catch(e){alert(e.message,'error');}finally{button.disabled=false;}}
  async function rowAction(action,i){const inv=state.invoices[i];if(action==='preview')return previewInvoice(i);if(action==='send'){state.selected=new Set([i]);return openSendDialog([inv]);}if(action==='resend'){state.selected=new Set([i]);return openResendDialog(C.classifySendSelection([inv]));}if(action==='disable')return openDisableDialog(inv);}
  function selectBy(mode){state.selected.clear();state.invoices.forEach((x,i)=>{if(mode==='all'||mode==='visible'||mode==='unsent'&&C.isInitialSendable(x)||mode==='failed'&&x.sendStatus==='送信失敗'||mode==='expired'&&x.dlStatus==='期限切れ')state.selected.add(i);});renderInvoices();}
  async function refreshAll(processPending=true){try{if(processPending)await api('processPendingSends');const data=await api('getDashboard');state.invoices=data.invoices||state.invoices;state.history=data.history||[];if(Array.isArray(data.partners)){state.partners=data.partners;persistPartners();renderPartners();renderPartnerOptions();}renderInvoices();renderHistory();$('#userLabel').textContent=data.user||'接続済み';}catch(e){alert(e.message,'error');}}
  function saveForm(form,key){const values=Object.fromEntries(new FormData(form).entries());state.settings={...state.settings,...values};localStorage.setItem('stepInvoiceSettings',JSON.stringify(state.settings));alert('設定を保存しました。','success');return values;}
  function restoreForms(){$$('#settingsForm [name],#mailForm [name]').forEach(el=>{if(state.settings[el.name]!==undefined)el.value=state.settings[el.name];});}
  $$('.nav-item').forEach(b=>b.onclick=()=>showView(b.dataset.view));
  $$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
  $$('[data-create-method]').forEach(b=>b.onclick=()=>setCreateMethod(b.dataset.createMethod));
  $('#invoiceCsv').onchange=e=>e.target.files[0]&&onInvoiceCsv(e.target.files[0]);
  $('#invoiceCsvFromList').onchange=async e=>{if(!e.target.files[0])return;showView('create');setCreateMethod('csv');await onInvoiceCsv(e.target.files[0]);e.target.value='';};
  $('#createInvoiceFromList').onclick=()=>{showView('create');setCreateMethod('single');};
  $('#partnerCsv').onchange=e=>e.target.files[0]&&onPartnerCsv(e.target.files[0]);
  $('#loadDemoPartners').onclick=loadDemoPartners;
  $('#goPartnerCreate').onclick=goToPartnerCreate;
  $('#openPartnerForm').onclick=()=>openPartnerForm();
  $('#partnerForm').onsubmit=savePartner;
  $('#deletePartnerForm').onsubmit=deletePartner;
  $('#deletePartnerCodeInput').oninput=updateDeleteConfirmation;
  $('#deletePartnerCheck').onchange=updateDeleteConfirmation;
  $('#partnerForm').elements.postal.addEventListener('change',lookupPostal);
  $('#partnerForm').elements.postal.addEventListener('blur',lookupPostal);
  $('#openStudentImport').onclick=openStudentImport;
  $('#studentSearchForm').onsubmit=searchStudent;
  $('#studentSearchForm').elements.studentChoice.onchange=()=>{$('#importStudentPartner').disabled=!$('#studentSearchForm').elements.studentChoice.checked;};
  $('#importStudentPartner').onclick=importStudentPartner;
  $('#addSingleDetail').onclick=()=>addSingleDetail();
  $('#previewSingleInvoice').onclick=previewSingleInvoice;
  $('#singleInvoiceForm').onsubmit=addSingleInvoice;
  $('#singleInvoiceForm').elements.invoiceDate.onchange=updateSingleFromDate;
  $('#addToSend').onclick=()=>{activateStep(5);showView('invoices');renderInvoices();};
  $('#downloadPreview').onclick=()=>state.preview&&createPdf(state.preview,{save:true,preview:true}).catch(e=>alert(e.message,'error'));
  $('#printPreview').onclick=printPreview;
  $('#confirmInvoiceMail').onclick=confirmInvoiceMail;
  $('#downloadSelectedInvoice').onclick=()=>state.preview&&createPdf(state.preview,{save:true}).catch(e=>alert(e.message,'error'));
  $('#printSelectedInvoice').onclick=()=>{if(!state.preview)return;$('#invoicePdfDialog').close();showInvoicePreview(state.preview);setTimeout(printPreview,50);};
  $('#editInvoiceForm').onsubmit=saveInvoiceEdit;
  $('#addEditInvoiceDetail').onclick=()=>addEditDetail();
  $('#deleteInvoiceForm').onsubmit=deleteInvoice;
  $('#deleteInvoiceNumberInput').oninput=updateInvoiceDeleteConfirmation;
  $('#deleteInvoiceCheck').onchange=updateInvoiceDeleteConfirmation;
  $('#invoiceDateField').onchange=updateInvoiceFilters;
  $('#invoiceDateFrom').onchange=updateInvoiceFilters;
  $('#invoiceDateTo').onchange=updateInvoiceFilters;
  $('#invoiceFreeSearch').oninput=updateInvoiceFilters;
  $('#clearInvoiceSearch').onclick=clearInvoiceFilters;
  $('#confirmSend').onclick=confirmSend;
  $('#confirmResend').onclick=confirmResend;
  $('#confirmDisable').onclick=confirmDisable;
  $$('[data-select]').forEach(b=>b.onclick=()=>selectBy(b.dataset.select));
  $('#refreshInvoices').onclick=refreshAll;
  $('#refreshHistory').onclick=refreshAll;
  $('#settingsForm').onsubmit=e=>{e.preventDefault();saveForm(e.target,'settings');};
  $('#mailForm').onsubmit=e=>{e.preventDefault();saveForm(e.target,'mail');};
  $('#sendTest').onclick=()=>alert('請求書を1件選択して、請求書一覧からテスト送信してください。');
  $('#loadSample').onclick=()=>{state.invoices=C.matchPartners([{partnerName:'テスト太郎',subject:'2026年8月分',invoiceDate:'2026/07/10',dueDate:'2026/07/27',invoiceNumber:'999999001',subtotal:25955,sourceTax:2595,sourceTotal:28550,tax:2595,total:28550,honorific:'様',postal:'487-0024',prefecture:'愛知県',address1:'春日井市テスト町1-2-3',address2:'',customerCode:'TEST001',note:'これは検証用の架空データです。',details:[{name:'8月分授業料',unitPrice:23455,quantity:1,amount:23455},{name:'8月分諸経費',unitPrice:2500,quantity:1,amount:2500}],pdfStatus:'未作成',sendStatus:'未送信',dlStatus:'未取得',warnings:[]}],state.partners);renderCreate();activateStep(2);};
  restoreForms();renderPartners();renderPartnerOptions();addSingleDetail();setSingleDefaults();renderCreate();renderInvoices();renderHistory();showView(location.hash.slice(1)||'invoices');
  if(localStorage.getItem(STAFF_AUTH_KEY))refreshAll();
})();
